From 64b88a1bf86399e12dc9e3924d2aea7eb8a1782d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:51:19 +0100
Subject: [PATCH] shell/panelview: move the blur region along with a
 de-floating panel

The blur region only followed the panel background's size, so while the
panel de-floated or re-floated it lagged behind the moving background,
showing a strip of wallpaper. Also update it when the background moves.

BUG: 511379
---
 shell/panelview.cpp | 3 +++
 1 file changed, 3 insertions(+)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..db529a95c2 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -1575,6 +1575,9 @@ void PanelView::handleQmlStatusChange(QQmlComponent::Status status)
         const QVariant maskProperty = rootObject->property("panelMask");
         if (static_cast<QMetaType::Type>(maskProperty.typeId()) == QMetaType::QRegion) {
             connect(rootObject, SIGNAL(panelMaskChanged()), this, SLOT(updateMask()));
+            if (rootObject->metaObject()->indexOfSignal("floatingTranslucentItemOffsetChanged()") >= 0) {
+                connect(rootObject, SIGNAL(floatingTranslucentItemOffsetChanged()), this, SLOT(updateMask()));
+            }
             updateMask();
         }
         if (touchingWindowSignal >= 0) {
